# PUT /api/sheets/{sheetId}/people/{personId}/merge — a steward merges the person into another person of the sheet.
# Body: { "intoId": <id> }.
guard:
  class: net.officefloor.hq.app.role.GuardViewer
  next: archived
archived:
  class: net.officefloor.hq.app.sheet.GuardArchived
  next: validate
validate:
  class: net.officefloor.hq.app.person.ValidateMerge
  next: before
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.sheet.LoadOrCreateSheet
  govern: [ transaction ]
  next: person
person:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.person.ApplyMerge
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.person.AuditPersonMerged
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithMergedInto
  govern: [ transaction ]
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads from the body the id of the person to merge into. */
public class ValidateMerge {

    public record MergeRequest(Long intoId) {
    }

    public void validate(@RequestBody(required = false) MergeRequest request, Out<MergeInput> body)
            throws InvalidPersonException {
        if (request == null || request.intoId() == null) {
            throw new InvalidPersonException("Choose a person to merge into.");
        }
        body.set(new MergeInput(request.intoId()));
    }
}
