package net.officefloor.hq.app.person;

import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.claim.ClerkLimitException;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

/** Undoing a transfer: only a steward, only for a person a transfer brought here, and only on the sheet's today they
 *  arrived. Publishes the transfer back to the sheet they came from. */
public class ValidateTransferUndo {
    public void validate(@Val Person person, @Val Sheet sheet, RoleRepository roles,
            @RequestHeader(name = "X-User", required = false) String userHeader, Out<TransferInput> body)
            throws InvalidPersonException, ClerkLimitException {
        String user = AuditUser.decode(userHeader);
        if (!Role.STEWARD.equals(roles.roleOf(person.getSheetId(), user))) {
            throw new ClerkLimitException("Only a steward can undo a transfer.");
        }
        if (person.getOriginSheet() == null || person.getArrivedOn() == null) {
            throw new InvalidPersonException("The person did not arrive by transfer.");
        }
        if (!person.getArrivedOn().equals(sheet.getToday())) {
            throw new InvalidPersonException("A transfer can only be undone on the day the person arrived.");
        }
        body.set(new TransferInput(person.getOriginSheet()));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.history.AsOf;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

/** Records, after the transfer back's own lines, that the transfer was undone on this sheet, then its rollup lines. */
public class AuditTransferUndone {
    public void audit(@Val PersonTransferred transferred, @Val Rollup before, SheetRepository sheets,
            PersonRepository people, ClaimRepository claims, RateRepository rates, PersonGradeRepository grades, AsOf asOf,
            @RequestHeader(name = "X-User", required = false) String userHeader, Audit audit) {
        String user = AuditUser.decode(userHeader);
        String here = transferred.fromSheet();
        audit.record("PERSON_TRANSFER_UNDONE sheet=" + here + " by=" + user + " name=" + transferred.name() + " to="
                + transferred.toSheet());
        Rollup.of(here, sheets, people, claims, rates, grades, asOf).changesSince(before, here, user)
                .forEach(audit::record);
    }
}
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/submitOnce';
import { useRowAction } from '../../api/rowAction';
import { PeopleColumns, PersonCells } from '../../slots/defs/peopleColumns';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { peoplePath, type Person } from './people';

// The button that undoes the transfer that brought this person here (a steward only, on the sheet's today they
// arrived): they are transferred back to the sheet they came from and leave this sheet's list.
function TransferUndoHeader() {
  return <th>Undo transfer</th>;
}

function PersonTransferUndo({ person }: { person: Person }) {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const queryClient = useQueryClient();
  const undo = useMutation({
    mutationFn: () => putJson<unknown>(`${peoplePath(sheet ?? '')}/${person.id}/transfer-undo`, {}, user),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: ['sheet', sheet ?? ''] });
    },
  });
  const submit = useSubmitOnce(undo);
  const rowAction = useRowAction(`person-${person.id}`);
  return (
    <td>
      <button
        type="button"
        data-testid="person-transfer-undo"
        disabled={undo.isPending}
        onClick={() => { rowAction.take(); submit(undefined); }}
      >
        Undo transfer
      </button>
      {undo.isError && rowAction.isLatest && (
        <span data-testid="person-error">The transfer could not be undone.</span>
      )}
    </td>
  );
}

export const contributions = [
  PeopleColumns.fill({ order: 50.5, Component: TransferUndoHeader }),
  PersonCells.fill({ order: 50.5, Component: PersonTransferUndo }),
];
